// Окно уровня «עלית דרגה — המשך כך» (MilestoneWindow, #milestone-window) на /journey.
//
// Как работает приложение после фикса #22c9d541 (commit 3dd6527, миграция 20261004160000):
//   признак «уровень уже показан» хранится в АККАУНТЕ — user_profiles.last_announced_rung — и дублируется на устройстве
//   localStorage['journey'] = {"state":{"lastAnnouncedRung":{"<profileId>":N},"pendingAchievements":{}},"version":0}.
//   Окно показывается, только если уровень выше И значения на устройстве, И значения в аккаунте; «סגירה» пишет уровень
//   в аккаунт (только вверх). Пока окно нигде не закрыто, оно может показаться и на втором устройстве — норма (context.md).
//   ВАЖНО: ключ на устройстве — id профиля (profiles.id), а НЕ auth user.id (у user1: профиль c750744f-…, auth 8e37439d-…).
//
// Когда нужен suppressMilestoneWindow:
//   - НЕ нужен из-за нового входа / чистого браузера: user1 уже на уровне 10, в аккаунте last_announced_rung = 10 → окна нет
//     (это и проверяет JR-06, без подавления).
//   - Нужен (страховка) в тестах, где уровень может измениться: завершение молитв (@data) и подмена ответов
//     prayer_completions / user_profiles (mock-данные с другим числом молитв), а также как защита от окна достижений
//     в очереди. Существующие вызовы в тестах оставлены — смысл проверок не меняется.
//
// Кнопки окна: #milestone-window-close (aria-label «סגירה») — просто закрывает;
//   #milestone-window-dismiss («חזרה למסך ראשי») — закрывает И уводит на /home, поэтому для страховки не используется.
import { Browser, BrowserContextOptions, expect, Page, TestInfo } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

/** Известные id профилей тестовых аккаунтов (ключи lastAnnouncedRung). */
const KNOWN_PROFILE_IDS = ['c750744f-6d79-4dd5-a891-0b3446eb08cd'];
const SUPPRESS_RUNG = 99;

/**
 * До навигации: в localStorage['journey'] выставить lastAnnouncedRung = 99 для всех известных id,
 * не затирая прочие поля store (pendingAchievements, version и т. д.).
 * Init script срабатывает перед каждой загрузкой документа (goto/reload).
 * По умолчанию дополнительно ставит автозакрытие окна (page.addLocatorHandler) — страховка, если id профиля неизвестен.
 * autoDismiss: false — для тестов, которые сами открывают окно достижения (тот же компонент).
 */
export async function suppressMilestoneWindow(
  page: Page,
  opts: { autoDismiss?: boolean; extraIds?: string[] } = {},
): Promise<void> {
  const ids = [...KNOWN_PROFILE_IDS, ...(opts.extraIds ?? [])];
  await page.addInitScript(
    ({ ids, rung }) => {
      try {
        const all = new Set<string>(ids);
        const authRe = /^sb-.+-auth-token$/;
        for (const k of Object.keys(localStorage)) {
          if (!authRe.test(k)) continue;
          try {
            const id = JSON.parse(localStorage.getItem(k) ?? 'null')?.user?.id;
            if (typeof id === 'string' && id) all.add(id);
          } catch {
            /* повреждённый токен — пропускаем */
          }
        }
        let root: any = null;
        try {
          root = JSON.parse(localStorage.getItem('journey') ?? 'null');
        } catch {
          root = null;
        }
        if (!root || typeof root !== 'object') root = { state: {}, version: 0 };
        const state = root.state && typeof root.state === 'object' ? root.state : {};
        const rungs: Record<string, number> = { ...(state.lastAnnouncedRung ?? {}) };
        for (const id of Object.keys(rungs)) all.add(id);
        for (const id of all) rungs[id] = Math.max(Number(rungs[id]) || 0, rung);
        root.state = { pendingAchievements: {}, ...state, lastAnnouncedRung: rungs };
        if (root.version === undefined) root.version = 0;
        localStorage.setItem('journey', JSON.stringify(root));
      } catch {
        /* about:blank / нет доступа к localStorage — пропускаем */
      }
    },
    { ids, rung: SUPPRESS_RUNG },
  );
  if (opts.autoDismiss !== false) {
    // noWaitAfter: если за окном уровня в очереди следующее — обработчик сработает снова перед следующим действием.
    await page.addLocatorHandler(
      page.locator('#milestone-window'),
      async (win) => {
        await win.getByRole('button', { name: 'סגירה' }).click();
      },
      { noWaitAfter: true },
    );
  }
}

/**
 * Страховка: если окно уровня (#milestone-window) появилось в течение timeout — закрыть «סגירה»
 * и дождаться скрытия (повторяет, если следом показано следующее окно очереди).
 */
export async function dismissMilestoneIfShown(page: Page, timeout = 1_500): Promise<void> {
  const win = page.locator('#milestone-window');
  for (let i = 0; i < 5; i++) {
    const shown = await win
      .first()
      .waitFor({ state: 'visible', timeout: i === 0 ? timeout : 1_000 })
      .then(
        () => true,
        () => false,
      );
    if (!shown) return;
    await win.getByRole('button', { name: 'סגירה' }).click();
    await expect(win).toBeHidden({ timeout: 10_000 });
  }
}

/**
 * «Новое устройство / другой браузер / после очистки данных сайта»: новый контекст с сессией аккаунта,
 * но БЕЗ ключа localStorage['journey'] (признак показанного уровня на устройстве). Параметры окна — из текущего проекта.
 * Файл сессии не меняется. Контекст закрывает вызывающий (ctx.close()).
 */
export async function openWithoutJourneyKey(browser: Browser, testInfo: TestInfo, account = 'user1'): Promise<{ page: Page; close: () => Promise<void> }> {
  const file = path.resolve(__dirname, '../../../auth', `${account}.json`);
  const state = JSON.parse(fs.readFileSync(file, 'utf8'));
  for (const o of state.origins ?? []) o.localStorage = (o.localStorage ?? []).filter((i: { name: string }) => i.name !== 'journey');
  const keys = ['baseURL', 'locale', 'viewport', 'userAgent', 'deviceScaleFactor', 'isMobile', 'hasTouch', 'timezoneId'] as const;
  const use = testInfo.project.use as Record<string, unknown>;
  const opts: BrowserContextOptions = {};
  for (const k of keys) if (use[k] !== undefined) (opts as Record<string, unknown>)[k] = use[k];
  const ctx = await browser.newContext({ ...opts, storageState: state });
  const page = await ctx.newPage();
  return { page, close: () => ctx.close() };
}

/** Окно уровня/достижения не появляется в течение `ms` (опрос каждые 250 мс). */
export async function expectNoMilestoneWindow(page: Page, ms = 6_000): Promise<void> {
  const win = page.locator('#milestone-window');
  const deadline = Date.now() + ms;
  while (Date.now() < deadline) {
    expect(await win.isVisible(), 'окно #milestone-window появилось').toBe(false);
    expect(await page.getByText('עלית דרגה', { exact: false }).isVisible(), 'появился текст «עלית דרגה»').toBe(false);
    await page.waitForTimeout(250);
  }
}
